75	// --- 核心场景：id 与 version 合法，kind/severity/invariant 为 null 也必须拒绝 ---
76	
77	func TestParseAuditNullRuleDefinitionTextRejected(t *testing.T) {
78		for _, field := range []string{"kind", "severity", "invariant"} {
79			t.Run(field, func(t *testing.T) {
80				// 没有检查记录：规则只会依据 invariant 布尔值得出结论，与类型关无关。
81				rule := ruleObject(`"id":"r1"`, `"`+field+`":null`,
82					`"requiresABI":false`, `"version":"1.0.0"`)
83				in := ruleTextSubmission("["+rule+"]", `"invariants":{"inv":true}`)
84				expectInvalidRuleText(t, in, "rules[0]", "r1", field)
85			})
86		}
87	}
88	
89	// --- 五个文本成员写成 null 都整份拒绝；id 自身非法时只凭位置定位 ---
90	
91	func TestParseAuditNullRuleTextFieldsRejected(t *testing.T) {
92		for _, field := range submissionRuleTextFields {
93			t.Run(field, func(t *testing.T) {
94				// id 自身为 null 时没有可点名的合法规则标识，其余字段仍可定位规则。
95				id := "r1"
96				if field == "id" {
97					id = ""
98				}
99				expectInvalidRuleText(t, ruleTextSubmission("["+ruleTextWithValue(field, "null")+"]"),
100					"rules[0]", id, field)
101			})
102		}
103	}
104	
105	// --- 布尔值、数字、对象、数组同样整份拒绝，不能被当成空字符串 ---
106	
107	// ruleTextWithValue 构造一条五个文本成员齐全的规则，仅把 field 的值换成
108	// 原始片段 val（其余成员保持合法字符串）。
109	func ruleTextWithValue(field, val string) string {
110		values := map[string]string{
111			"id": `"r1"`, "kind": `"static"`, "severity": `"high"`,
112			"invariant": `"inv"`, "version": `"1.0.0"`,
113		}
114		values[field] = val
115		members := make([]string, 0, len(submissionRuleTextFields))
116		for _, f := range submissionRuleTextFields {
117			members = append(members, `"`+f+`":`+values[f])
118		}
119		return ruleObject(members...)
120	}
121	
122	func TestParseAuditNonStringRuleTextFieldsRejected(t *testing.T) {
123		values := []string{"true", "false", "0", "123", "{}", "[]", `["x"]`}
124		for _, field := range submissionRuleTextFields {
125			for _, val := range values {
126				t.Run(field+"/"+val, func(t *testing.T) {
127					in := ruleTextSubmission("[" + ruleTextWithValue(field, val) + "]")
128					artifact, _, _, _, err := ParseAuditInput([]byte(in))
129					if err == nil {
130						t.Fatalf("%s=%s must reject the whole submission", field, val)
131					}
132					if !strings.Contains(err.Error(), "rules[0]") ||
133						!strings.Contains(err.Error(), field+" must be a string") {
134						t.Fatalf("error must name the position, field and string requirement: %v", err)
135					}
136					if artifact != (Artifact{}) {
137						t.Fatalf("rejection must return no partial artifact: %+v", artifact)
138					}
139				})
140			}
141		}
142	}
143	
144	// --- 位置与点名：出错规则按数组下标定位，规则内按正式字段顺序报第一个 ---
145	
146	func TestParseAuditRuleTextErrorNamesPositionAndID(t *testing.T) {
147		// 第二条规则非法：错误必须点名 rules[1] 与它的合法 id，而不是第一条。
148		rules := "[" +
149			ruleObject(`"id":"r0"`, `"kind":"static"`, `"severity":"low"`, `"invariant":"i0"`, `"version":"1"`) + "," +
150			ruleObject(`"id":"r2"`, `"kind":null`, `"severity":"high"`, `"invariant":"i2"`, `"version":"2"`) +
151			"]"
152		expectInvalidRuleText(t, ruleTextSubmission(rules), "rules[1]", "r2", "kind")
153	
154		// 同一规则内多个字段非法且书写顺序任意：按 id、kind、severity、
155		// invariant、version 的正式顺序报第一个，这里是 kind 而不是 severity。
156		rule := `{"severity":null,"invariant":null,"id":"r9","kind":null,"version":"9"}`
157		expectInvalidRuleText(t, ruleTextSubmission("["+rule+"]"), "rules[0]", "r9", "kind")
158	
159		// 多条规则非法：报数组中最靠前的一条。
160		twoBad := "[" +
161			ruleObject(`"id":"a"`, `"version":"1"`, `"severity":null`) + "," +
162			ruleObject(`"id":"b"`, `"version":"2"`, `"kind":null`) +
163			"]"
164		_, _, _, _, err := ParseAuditInput([]byte(ruleTextSubmission(twoBad)))
165		if err == nil || !strings.Contains(err.Error(), "rules[0]") ||
166			!strings.Contains(err.Error(), "severity must be a string") {
167			t.Fatalf("the first offending rule must be reported by its array index: %v", err)
168		}
169	}
