196	// --- 省略成员仍取默认值；显式空字符串是合法字符串，业务判断保持原样 ---
197	
198	func TestParseAuditRuleTextOmittedAndExplicitEmpty(t *testing.T) {
199		// 省略 kind/severity/invariant：解析合法，三者取零值 ""。
200		omitted := ruleTextSubmission("[" + ruleObject(`"id":"r1"`, `"version":"1.0.0"`) + "]")
201		aOmit, rulesOmit, _, _, err := ParseAuditInput([]byte(omitted))
202		if err != nil {
203			t.Fatalf("omitted text members must keep their defaults: %v", err)
204		}
205		if rulesOmit[0].Kind != "" || rulesOmit[0].Severity != "" || rulesOmit[0].Invariant != "" {
206			t.Fatalf("omitted members must decode to empty strings: %+v", rulesOmit[0])
207		}
208	
209		// 显式空字符串：同样解析合法，规则定义与省略写法逐字段相同，报告标识一致。
210		explicitEmpty := ruleTextSubmission("[" + ruleObject(
211			`"id":"r1"`, `"kind":""`, `"severity":""`, `"invariant":""`, `"version":"1.0.0"`) + "]")
212		aEmpty, rulesEmpty, _, _, err := ParseAuditInput([]byte(explicitEmpty))
213		if err != nil {
214			t.Fatalf("explicit empty strings must be legal strings: %v", err)
215		}
216		if aEmpty != aOmit || len(rulesEmpty) != 1 || rulesEmpty[0] != rulesOmit[0] {
217			t.Fatalf("omitted and explicit-empty must decode to the same values")
218		}
219		if strictParsedReport(t, omitted).ReportID != strictParsedReport(t, explicitEmpty).ReportID {
220			t.Fatal("omitted and explicit-empty text must share the report id")
221		}
222	
223		// 显式空 id：通过类型关，但仍被既有“rule id is required”业务规则拒绝。
224		emptyID := ruleTextSubmission("[" + ruleObject(`"id":""`, `"version":"1.0.0"`) + "]")
225		a, rules, _, _, err := ParseAuditInput([]byte(emptyID))
226		if err != nil {
227			t.Fatalf("an explicit empty id is a legal string and must parse: %v", err)
228		}
229		if _, err := BuildReport(a, rules, nil, nil); err == nil ||
230			!strings.Contains(err.Error(), "rule id is required") ||
231			strings.Contains(err.Error(), "must be a string") {
232			t.Fatalf("an empty id must keep the required-id business error, got: %v", err)
233		}
234	
235		// 显式空 version：仍是既有必填版本业务错误，不是类型错误。
236		emptyVersion := ruleTextSubmission("[" + ruleObject(`"id":"r1"`, `"version":""`) + "]")
237		a, rules, _, _, err = ParseAuditInput([]byte(emptyVersion))
238		if err != nil {
239			t.Fatalf("an explicit empty version is a legal string and must parse: %v", err)
240		}
241		if _, err := BuildReport(a, rules, nil, nil); err == nil ||
242			!strings.Contains(err.Error(), "version is required") ||
243			strings.Contains(err.Error(), "must be a string") {
244			t.Fatalf("an empty version must keep the required-version business error, got: %v", err)
245		}
246	}
247	
248	// --- 合法字符串逐字保留：中文、换行与前后空格，且产物哈希与报告标识保持原值 ---
249	
250	func TestParseAuditLegalRuleTextPreservedVerbatim(t *testing.T) {
251		id := " 规则 1\n "
252		kind := " 静态\n类型 "
253		severity := " 高 "
254		invariant := "不变式\nx"
255		version := " v1\n "
256		rule := ruleObject(
257			`"id":`+jsonString(id),
258			`"kind":`+jsonString(kind),
259			`"severity":`+jsonString(severity),
260			`"invariant":`+jsonString(invariant),
261			`"requiresABI":false`,
262			`"version":`+jsonString(version),
263		)
264		in := ruleTextSubmission("["+rule+"]", `"invariants":{`+jsonString(invariant)+`:false}`)
265	
266		artifact, rules, invariants, checks, err := ParseAuditInput([]byte(in))
267		if err != nil {
268			t.Fatalf("a legal submission with CJK/newline/whitespace text must parse: %v", err)
269		}
270		got := rules[0]
271		if got.ID != id || got.Kind != kind || got.Severity != severity ||
272			got.Invariant != invariant || got.Version != version {
273			t.Fatalf("rule text must be preserved verbatim:\n%+v", got)
274		}
275		if invariants[invariant] != false {
276			t.Fatalf("the invariant conclusion must bind to the verbatim name: %+v", invariants)
277		}
278		if ArtifactHash(artifact) != ArtifactHash(strictTestArtifact()) {
279			t.Fatal("legal text must keep the original artifact hash")
280		}
281	
282		// 与同样字段直接构造的 Go 值构建出的报告共享标识，缺陷证据逐字保留。
283		directArtifact := strictTestArtifact()
284		directRules := []Rule{{ID: id, Kind: kind, Severity: severity, Invariant: invariant, Version: version}}
285		want, err := BuildReport(directArtifact, directRules, map[string]bool{invariant: false}, nil)
286		if err != nil {
287			t.Fatal(err)
288		}
289		report, err := BuildReport(artifact, rules, invariants, checks)
290		if err != nil {
291			t.Fatalf("a legal submission must build a report: %v", err)
292		}
293		if report.ReportID != want.ReportID {
294			t.Fatalf("report id must keep its existing value:\n got %s\nwant %s", report.ReportID, want.ReportID)
295		}
296		if len(report.Findings) != 1 {
297			t.Fatalf("inv=false must produce exactly one finding, got %+v", report.Findings)
298		}
299		f := report.Findings[0]
300		if f.RuleID != id || f.Severity != severity || f.Invariant != invariant || f.Version != version {
301			t.Fatalf("finding must bind the verbatim rule text: %+v", f)
302		}
303		if f.Evidence != invariantEvidence(invariant) {
304			t.Fatalf("evidence must be the verbatim invariant text, got %q", f.Evidence)
305		}
306	}
307	
308	// --- 大小写变体、带空格名称与未知成员是扩展信息：其中的 null 不触发错误，
309	// 合法字符串也不能补上缺失字段或挽救非法正式字段（无论写在前还是后） ---
310	
311	func TestParseAuditRuleTextVariantsIgnored(t *testing.T) {
312		// 正式 kind 省略，变体携带 null 或字符串：只是扩展信息，kind 仍取零值，
313		// 报告标识与不含任何变体的提交一致。
314		plain := ruleTextSubmission("[" + ruleObject(`"id":"r1"`, `"version":"1.0.0"`) + "]")
315		for _, ext := range []string{
316			`"Kind":null`,
317			`" kind ":null`,
318			`"mystery":null`,
319			`"Kind":"symbolic"`,
320			`" kind ":" static "`,
321		} {
322			rule := ruleObject(`"id":"r1"`, `"version":"1.0.0"`, ext)
323			got := strictParsedReport(t, ruleTextSubmission("["+rule+"]"))
324			if got.Rules[0].Kind != "" {
325				t.Fatalf("extension member %s must not supply a missing formal kind: %+v", ext, got.Rules[0])
326			}
327			if got.ReportID != strictParsedReport(t, plain).ReportID {
328				t.Fatalf("extension member %s changed the report id", ext)
329			}
330		}
331	
332		// 正式 kind 为 null，旁边的变体携带合法字符串（位于其前或其后）都不能挽救。
333		for _, pos := range []string{"before", "after"} {
334			t.Run(pos, func(t *testing.T) {
335				var members []string
336				if pos == "before" {
337					members = []string{`"id":"r1"`, `"Kind":"static"`, `"kind":null`, `"version":"1.0.0"`}
338				} else {
339					members = []string{`"id":"r1"`, `"kind":null`, `" kind ":"static"`, `"version":"1.0.0"`}
340				}
341				expectInvalidRuleText(t, ruleTextSubmission("["+ruleObject(members...)+"]"),
342					"rules[0]", "r1", "kind")
343			})
344		}
345	}
346	
347	// --- Unicode 转义写出的正式名称遵守同一字符串规则 ---
348	
349	func TestParseAuditEscapedRuleTextNameFollowsSameRule(t *testing.T) {
350		// "kind" 的首字母 k 的码位是 0x6b：转义写出后解码仍是正式 kind，null 拒绝。
351		escName := "\\" + "u006b" + "ind"
352		rule := ruleObject(`"id":"r1"`, `"`+escName+`":null`, `"version":"1.0.0"`)
353		in := ruleTextSubmission("[" + rule + "]")
354		if !strings.Contains(in, `\`+"u006bind") {
355			t.Fatalf("test setup must carry the JSON escape, got %s", in)
356		}
357		expectInvalidRuleText(t, in, "rules[0]", "r1", "kind")
358	
359		// 转义写法携带合法字符串时，与直接书写解析到同一规则、同一报告标识。
360		escaped := ruleTextSubmission("[" + ruleObject(
361			`"id":"r1"`, `"`+escName+`":"static"`, `"severity":"high"`,
362			`"invariant":"inv"`, `"requiresABI":false`, `"version":"1.0.0"`) + "]")
363		plainLegal := ruleTextSubmission("[" + artifactTextRule + "]")
364		if strictParsedReport(t, escaped).ReportID != strictParsedReport(t, plainLegal).ReportID {
365			t.Fatal("escaped and plain spellings of a legal string must share the report id")
366		}
367	}
