1	package main
2	
3	import (
4		"bytes"
5		"os"
6		"path/filepath"
7		"strings"
8		"testing"
9	)
10	
11	// 本文件在真实命令行进程边界上回归保护 report / diff 读取已保存报告时对
12	// requiresABI 类型的要求：正式 requiresABI 成员一旦出现就只能是 JSON 布尔
13	// 值。归档里把它写成 null（或字符串、数字、对象、数组）时，整份归档必须
14	// 判为损坏——非零退出、原因进 stderr（含报告标识、出错规则和 requiresABI
15	// 必须是布尔值），stdout 不出现任何报告片段，原归档原样保留，不会被自动
16	// 修补。省略该成员仍按 false 读回；RequiresABI、" requiresABI " 这类大小
17	// 写变体或带空格名称只是扩展信息，其中的值既不能触发错误，也不能挽救非
18	// 法的正式成员。diff 的任一侧遇到同样的归档，也必须在输出比较结果前失败。
19	
20	// injectRuleRequiresABI reads the archive named by id, locates the rule
21	// object with ruleID and replaces its formal requiresABI member with
22	// fragment (e.g. `"requiresABI":null`). The mutated bytes are written back
23	// and returned so tests can assert the failed read leaves them untouched.
24	func injectRuleRequiresABI(t *testing.T, store, id, ruleID, fragment string) []byte {
25		t.Helper()
26		path := filepath.Join(store, id+".json")
27		data, err := os.ReadFile(path)
28		if err != nil {
29			t.Fatal(err)
30		}
31		doc := string(data)
32		head := `"id":"` + ruleID + `"`
33		idx := strings.Index(doc, head)
34		if idx < 0 {
35			t.Fatalf("test setup: rule %s not found in archive", ruleID)
36		}
37		rest := doc[idx:]
38		marker := `"requiresABI":`
39		at := strings.Index(rest, marker)
40		if at < 0 {
41			t.Fatalf("test setup: rule %s has no requiresABI member", ruleID)
42		}
43		valueStart := idx + at + len(marker)
44		comma := strings.IndexByte(doc[valueStart:], ',')
45		if comma < 0 {
46			t.Fatalf("test setup: rule %s requiresABI value has no trailing comma", ruleID)
47		}
48		valueEnd := valueStart + comma
49		out := doc[:idx+at] + fragment + doc[valueEnd:]
50		if out == doc {
51			t.Fatal("test setup: injection did not change the archive")
52		}
53		if err := os.WriteFile(path, []byte(out), 0o644); err != nil {
54			t.Fatal(err)
55		}
56		return []byte(out)
57	}
58	
59	// assertRequiresABICorruptFailure asserts the full CLI failure contract for
60	// an illegal formal requiresABI value.
61	func assertRequiresABICorruptFailure(t *testing.T, stdout, stderr string, code int, id, rule string) {
62		t.Helper()
63		if code == 0 {
64			t.Fatal("an archive with a non-boolean requiresABI must exit non-zero")
65		}
66		if !strings.Contains(stderr, "corrupt") {
67			t.Fatalf("stderr must classify the archive as corrupt:\n%s", stderr)
68		}
69		if !strings.Contains(stderr, id) {
70			t.Fatalf("stderr must name the report id %q:\n%s", id, stderr)
71		}
72		if !strings.Contains(stderr, rule) {
73			t.Fatalf("stderr must name the offending rule %q:\n%s", rule, stderr)
74		}
75		if !strings.Contains(stderr, "requiresABI must be a boolean") {
76			t.Fatalf("stderr must state requiresABI must be a boolean:\n%s", stderr)
77		}
78		if stdout != "" {
79			t.Fatalf("rejected read must print nothing to stdout, got:\n%s", stdout)
80		}
81	}
82	
83	// --- report：null 落在任何检查结论的规则上都失败，stdout 没有报告片段 ---
84	
85	func TestCLIReportNullRequiresABIFailsCleanly(t *testing.T) {
86		for _, tc := range []struct {
87			rule string
88		}{
89			{"rule-pass"},      // 通过
90			{"rule-defect"},    // 发现缺陷
91			{"rule-tool"},      // 工具缺失
92			{"rule-timeout"},   // 超时
93			{"rule-unchecked"}, // 未检查
94		} {
95			t.Run(tc.rule, func(t *testing.T) {
96				bin := auditBinary(t)
97				work := t.TempDir()
98				store := filepath.Join(work, "reports")
99				id := auditOneReport(t, bin, work, store)
100				mutated := injectRuleRequiresABI(t, store, id, tc.rule, `"requiresABI":null`)
101	
102				stdout, stderr, code := runCLIReport(t, bin, store, id)
103				assertRequiresABICorruptFailure(t, stdout, stderr, code, id, tc.rule)
104				for _, marker := range []string{`"reportId"`, `"rules"`, `"findings"`, "发现缺陷"} {
105					if strings.Contains(stdout, marker) {
106						t.Fatalf("stdout must not leak a report fragment %q:\n%s", marker, stdout)
107					}
108				}
109	
110				// 归档必须原样保留，不被自动修补。
111				kept, err := os.ReadFile(filepath.Join(store, id+".json"))
112				if err != nil {
113					t.Fatal(err)
114				}
115				if !bytes.Equal(kept, mutated) {
116					t.Fatalf("failed report read must leave the corrupt archive untouched:\n%s", kept)
117				}
118			})
119		}
120	}
121	
122	// --- report：字符串、数字、对象、数组都同样判为损坏 ---
123	
124	func TestCLIReportNonBooleanRequiresABIFailsCleanly(t *testing.T) {
125		for _, val := range []string{`"false"`, `0`, `1`, `{}`, `[true]`} {
126			t.Run(val, func(t *testing.T) {
127				bin := auditBinary(t)
128				work := t.TempDir()
129				store := filepath.Join(work, "reports")
130				id := auditOneReport(t, bin, work, store)
131				injectRuleRequiresABI(t, store, id, "rule-pass", `"requiresABI":`+val)
132	
133				stdout, stderr, code := runCLIReport(t, bin, store, id)
134				assertRequiresABICorruptFailure(t, stdout, stderr, code, id, "rule-pass")
135			})
136		}
137	}
138	
139	// --- report：变体名称中的值是扩展信息，既不触发错误也不能挽救正式 null ---
140	
141	func TestCLIReportRequiresABIVariantRules(t *testing.T) {
